mapper.update:
UPDATE account_state
SET login_state = #{pendingLoginState},
    last_state_sync_time = #{updatedAt},
    state_source = #{stateSource},
    updated_at = #{updatedAt}
WHERE (
    login_state IS NULL
    OR login_state = #{offlineLoginState}
  )
  AND account_id IN

  #{accountId}

UPDATE account_state
SET desired_login_state = #{desiredLoginState},
    updated_at = #{updatedAt}
WHERE account_id IN

  #{accountId}

UPDATE account_state
SET login_state = #{pendingLoginState},
    last_state_sync_time = #{updatedAt},
    state_source = #{targetStateSource},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND login_state = #{offlineLoginState}
  AND state_source = #{expectedStateSource}
  AND (desired_login_state IS NULL OR desired_login_state != #{desiredOfflineState})

UPDATE account_state
SET login_state = #{loginState},
    last_state_sync_time = #{lastStateSyncTime},
    state_source = #{stateSource},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}

UPDATE account_state
SET account_state = #{targetState},
    updated_at = #{updatedAt}
WHERE account_state = #{expectedState}
  AND account_id IN

  #{accountId}

UPDATE account_state state_row JOIN (
SELECT #{row.accountId} AS account_id, #{row.truthIp} AS truth_ip, #{row.proxyCountry} AS proxy_country, #{row.proxySource} AS proxy_source, #{row.updatedAt} AS updated_at
) snapshot ON snapshot.account_id = state_row.account_id SET state_row.truth_ip = snapshot.truth_ip, state_row.proxy_country = snapshot.proxy_country, state_row.proxy_source = snapshot.proxy_source, state_row.updated_at = snapshot.updated_at

UPDATE account_state
SET block_reason = #{blockReason},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}

mapper.select:
SELECT s.tenant_id AS tenantId,
       s.account_id AS accountId
FROM account_state s
INNER JOIN account a
  ON a.id = s.account_id
 AND a.tenant_id = s.tenant_id
 AND a.deleted_at IS NULL
WHERE s.login_state = #{offlineLoginState}
  AND s.state_source = #{stateSource}
  AND (s.desired_login_state IS NULL OR s.desired_login_state != #{desiredOfflineState})
  AND s.last_state_sync_time <= #{eligibleBefore}
ORDER BY s.last_state_sync_time ASC, s.id ASC
LIMIT #{limit}

mapper.update:
UPDATE account_state
SET fallback_message_restriction_until = CASE
      WHEN fallback_message_restriction_until IS NULL
        OR fallback_message_restriction_until < #{candidateUntil}
      THEN #{candidateUntil}
      ELSE fallback_message_restriction_until
    END,
    mute_status = CASE
      WHEN pulling_restriction_until IS NOT NULL
        AND pulling_restriction_until > #{now}
      THEN 3
      ELSE 1
    END,
    cooldown_until = GREATEST(
      #{candidateUntil},
      CASE WHEN fallback_message_restriction_until > #{now}
        THEN fallback_message_restriction_until ELSE 0 END,
      CASE WHEN pulling_restriction_until > #{now}
        THEN pulling_restriction_until ELSE 0 END),
    restriction_reason_code = CASE
      WHEN restriction_reported_at IS NULL
        OR restriction_reported_at <= #{occurredAt}
      THEN #{reasonCode}
      ELSE restriction_reason_code
    END,
    restriction_reported_at = CASE
      WHEN restriction_reported_at IS NULL
        OR restriction_reported_at < #{occurredAt}
      THEN #{occurredAt}
      ELSE restriction_reported_at
    END,
    updated_at = CASE WHEN updated_at > #{now} THEN updated_at ELSE #{now} END
WHERE account_id = #{accountId}
  AND #{candidateUntil} > #{now}
  AND (
    platform_message_restriction_reported_at IS NULL
    OR (
      (platform_message_restriction_until IS NULL
          AND #{occurredAt} > platform_message_restriction_reported_at)
      OR (platform_message_restriction_until IS NOT NULL
          AND platform_message_restriction_until <= #{now}
          AND #{occurredAt} > platform_message_restriction_until)
    )
  )
